contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount == 10 wei);
        require(address(this).balance >= amount);

        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint testBalanceBefore = address(this).balance;

        bool reverted;
        c.play{value: amount}(); if (__ESBMC_reverted()) return;

        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint testBalanceAfter = address(this).balance;

        bool increased = testBalanceAfter > testBalanceBefore;
        bool emptied = (potBefore > 0 && potAfter == 0);

        assert(increased == emptied && (!increased || testBalanceAfter >= testBalanceBefore + potBefore - 1));
    }

    receive() external payable {}
}

