// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        amount = 10 wei;
        vm.assume(address(this).balance >= amount);
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        uint testBalanceBefore = address(this).balance;
        bool reverted;
        try c.play{value: amount}() {} catch { return; }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        uint testBalanceAfter = address(this).balance;
        bool increased = testBalanceAfter > testBalanceBefore;
        bool emptied = (potBefore > 0 && potAfter == 0);
        assertTrue(increased == emptied && (!increased || testBalanceAfter >= testBalanceBefore + potBefore - 1));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
